/* Illustrated close-up photography, independent of the gameplay camera. */
function makeCloseup(kind,seed=0){const p=document.createElement('canvas');p.width=600;p.height=1000;const x=p.getContext('2d');const rnd=n=>{let v=Math.sin(n*81.9+seed*.37)*41718;return v-Math.floor(v)};const gradient=(a,b)=>{let q=x.createLinearGradient(0,0,600,1000);q.addColorStop(0,a);q.addColorStop(1,b);return q};x.fillStyle=gradient('#719e8e','#122f2c');x.fillRect(0,0,600,1000);function ellipse(a,b,c,d,color,rot=0){x.save();x.translate(a,b);x.rotate(rot);x.fillStyle=color;x.beginPath();x.ellipse(0,0,c,d,0,0,7);x.fill();x.restore()}function leaf(bx,by,tx,ty,width,color){x.fillStyle=color;x.beginPath();x.moveTo(bx,by);x.quadraticCurveTo(tx-width,ty+100,tx,ty);x.quadraticCurveTo(tx+width,ty+170,bx,by);x.fill();x.strokeStyle='#d8f4a72f';x.lineWidth=1.4;x.beginPath();x.moveTo(bx,by);x.quadraticCurveTo(tx,ty+130,tx,ty);x.stroke()}function mountains(){x.fillStyle=gradient('#a0cec2','#4d8777');x.fillRect(0,0,600,1000);for(let k=0;k<3;k++){x.fillStyle=['#7a9e8b','#4c7e72','#2e5b53'][k];x.beginPath();x.moveTo(0,1000);for(let i=0;i<=620;i+=20)x.lineTo(i,390+k*100+Math.sin(i*.012+k)*65+Math.cos(i*.027)*25);x.lineTo(620,1000);x.fill()}ellipse(440,140,45,45,'#f5f0b5')}function grass(flowers){for(let i=0;i<35;i++){ellipse(rnd(i)*650,rnd(i+90)*900,12+rnd(i+7)*35,12+rnd(i+7)*35,'#d9ed9b0d')}for(let i=0;i<36;i++){let bx=rnd(i+2)*800-100,tx=bx+(rnd(i+3)-.5)*300,ty=130+rnd(i+4)*650;leaf(bx,1100,tx,ty,15+rnd(i+5)*55,['#376e4f','#448a5a','#74a86a','#93c579','#1e5748'][i%5])}for(let i=0;i<14;i++){let a=100+rnd(i+80)*420,b=300+rnd(i+90)*550;ellipse(a,b,2+rnd(i)*3,5,'#c9f7e9b0',.4)}if(flowers){for(let i=0;i<7;i++){let a=50+rnd(i+60)*500,b=250+rnd(i+66)*420;x.strokeStyle='#80a665';x.lineWidth=4;x.beginPath();x.moveTo(a+60,1000);x.quadraticCurveTo(a+40,b+180,a,b);x.stroke();for(let j=0;j<6;j++)ellipse(a+Math.cos(j)*17,b+Math.sin(j)*17,11,19,'#f5f0ca',j);ellipse(a,b,9,9,'#edc267')}}else{leaf(-50,1100,275,165,80,'#9bc47b');leaf(650,1100,330,380,100,'#3a926c');ellipse(265,400,7,12,'#d5fff3a0',-.3);ellipse(268,396,2,4,'#ffffffc0')}}function canopy(){x.fillStyle=gradient('#b5d1ad','#325c4a');x.fillRect(0,0,600,1000);for(let i=0;i<22;i++){let a=rnd(i)*600,b=rnd(i+10)*520;ellipse(a,b,50+rnd(i+3)*70,80,['#315c43','#51805a','#7fa572','#a1be82'][i%4])}for(let i=0;i<8;i++){let a=-200+i*160;x.fillStyle=i%2?'#425849':'#344738';x.beginPath();x.moveTo(a-70,1050);x.lineTo(300+(a-300)*.4,0);x.lineTo(310+(a-300)*.4,0);x.lineTo(a+70,1050);x.fill();x.strokeStyle='#9cb08344';x.lineWidth=3;x.beginPath();x.moveTo(a-30,1000);x.lineTo(300+(a-300)*.4,0);x.stroke()}for(let i=0;i<35;i++)leaf(rnd(i+6)*800-100,100+rnd(i+8)*600,rnd(i+9)*700,70+rnd(i+10)*500,20,'#618f5b');x.save();x.globalAlpha=.12;x.fillStyle='#f4f8ce';x.beginPath();x.moveTo(360,0);x.lineTo(520,1000);x.lineTo(250,1000);x.closePath();x.fill();x.restore()}function selfie(){mountains();x.save();x.translate(305,450);x.rotate(-.13);ellipse(0,390,205,275,'#224b51');ellipse(-150,470,72,210,'#376b70',-.5);ellipse(172,470,76,240,'#4d8586',.6);x.fillStyle='#78d8cd';x.beginPath();x.roundRect(-135,200,35,350,12);x.fill();x.fillStyle='#397f7e';x.beginPath();x.roundRect(95,200,35,350,12);x.fill();x.fillStyle='#74c5b8';x.beginPath();x.roundRect(-80,230,170,260,30);x.fill();x.strokeStyle='#c7f1d3';x.lineWidth=6;x.strokeRect(-40,290,90,75);ellipse(0,60,95,125,'#cca986');ellipse(-94,60,13,25,'#c4a07f');ellipse(94,60,13,25,'#c4a07f');x.fillStyle='#1d3937';x.beginPath();x.ellipse(0,-50,122,34,0,0,7);x.fill();x.beginPath();x.roundRect(-89,-116,180,71,[50,50,7,7]);x.fill();x.fillStyle='#7dcbb6';x.fillRect(-85,-62,172,12);x.fillStyle='#18302e';x.beginPath();x.roundRect(-81,8,72,42,14);x.roundRect(9,8,72,42,14);x.fill();x.strokeStyle='#152f2b';x.lineWidth=7;x.beginPath();x.moveTo(-12,20);x.lineTo(12,20);x.stroke();x.strokeStyle='#9ac8b4';x.lineWidth=2;x.beginPath();x.moveTo(-68,15);x.lineTo(-42,33);x.moveTo(24,15);x.lineTo(48,33);x.stroke();x.strokeStyle='#8e6556';x.lineWidth=3;x.beginPath();x.moveTo(-21,94);x.quadraticCurveTo(0,111,22,94);x.stroke();x.strokeStyle='#af8b6b';x.beginPath();x.moveTo(4,43);x.lineTo(0,72);x.lineTo(12,72);x.stroke();x.restore();leaf(-80,1100,80,720,65,'#234d3f');leaf(700,1100,540,690,65,'#547f55')}
if(kind==='grass')grass(false);else if(kind==='tree')canopy();else if(kind==='flower')grass(true);else selfie();let vign=x.createRadialGradient(300,420,180,300,500,680);vign.addColorStop(0,'#071c1700');vign.addColorStop(1,'#071c1766');x.fillStyle=vign;x.fillRect(0,0,600,1000);for(let i=0;i<6500;i++){x.fillStyle=i%2?'#ffffff05':'#00000005';x.fillRect(rnd(i+123)*600,rnd(i+223)*1000,1.5,1.5)}return p.toDataURL('image/jpeg',.92)}
